// Writes the text of every [data-hw] element in Nayan's handwriting, using the
// glyph sprite from handwriting.js (generated by tools/handwriting_sprite.py).
// Letters come from the sprite; anything else (digits, punctuation) falls back
// to the page font. Screen readers get the plain text.
(function () {
    var H = window.HANDWRITING;
    if (!H) { window.handwrite = function () {}; return; }

    var root = document.documentElement.style;
    root.setProperty('--hw-sprite', 'url(' + H.sprite + ')');
    root.setProperty('--hw-signature', 'url(' + H.signature.src + ')');
    root.setProperty('--sig-ratio', H.signature.w / H.signature.h);

    var k = 0.72 / H.cap;        // em per source pixel: capitals end up ~0.72em tall
    var em = function (px) { return (px * k).toFixed(4) + 'em'; };
    var maskSize = em(H.w) + ' ' + em(H.h);
    var kern = em(-9);           // glyphs carry 6px of padding on each side

    function write(el) {
        var text = el.textContent.trim();
        var visual = document.createElement('span');
        visual.setAttribute('aria-hidden', 'true');
        text.split(/\s+/).forEach(function (word, wi) {
            if (wi) visual.appendChild(document.createTextNode(' '));
            var w = document.createElement('span');
            w.className = 'hw-word';
            for (var i = 0; i < word.length; i++) {
                var ch = word[i], g = H.glyphs[ch];
                var s = document.createElement('span');
                if (!g) { s.className = 'hw-fb'; s.textContent = ch; w.appendChild(s); continue; }
                s.className = 'g';
                s.style.width = em(g.w);
                s.style.height = em(g.h);
                s.style.verticalAlign = em(g.base - g.h);
                s.style.marginRight = kern;
                s.style.webkitMaskSize = s.style.maskSize = maskSize;
                s.style.webkitMaskPosition = s.style.maskPosition = em(-g.x) + ' 0';
                w.appendChild(s);
            }
            visual.appendChild(w);
        });
        var label = document.createElement('span');
        label.className = 'sr-only';
        label.textContent = text;
        el.textContent = '';
        el.style.wordSpacing = '0.12em';
        el.append(label, visual);
        el.setAttribute('data-hw', 'done');
    }

    window.handwrite = function (scope) {
        scope = scope || document;
        if (scope.matches && scope.matches('[data-hw=""]')) write(scope);
        scope.querySelectorAll('[data-hw=""]').forEach(write);
    };
})();
